@Test
public void testConcurrency() {
    Random random = new Random();
    // Run the test 3 times
    for (int k = 0; k < 3; k++) {
        long startTime = System.currentTimeMillis();
        int numThreads = 30;
        int numHitsPerThread = 200000;
        int expectedHitCount = numThreads * numHitsPerThread;
        // Randomly set the time range.
        int timeRangeInSecond = random.nextInt(100) + 10;
        HitCounter hitCounter = new HitCounter(timeRangeInSecond);
        List<Thread> threadList = new ArrayList<>();
        for (int i = 0; i < numThreads; i++) {
            Thread thread = new Thread(() -> {
                for (int j = 0; j < numHitsPerThread; j++) {
                    hitCounter.hit(System.currentTimeMillis());
                }
            });
            thread.start();
            threadList.add(thread);
        }
        for (Thread thread : threadList) {
            Uninterruptibles.joinUninterruptibly(thread);
        }
        Assert.assertNotNull(hitCounter);
        Assert.assertEquals(hitCounter.getHitCount(), expectedHitCount);
        long duration = System.currentTimeMillis() - startTime;
        System.out.println(duration);
    }
}

@Test
public void testMaxHitRateTracker() {
    int timeInSec = 60;
    MaxHitRateTracker hitCounter = new MaxHitRateTracker(timeInSec);
    long currentTimestamp = System.currentTimeMillis();
    for (int i = 0; i < timeInSec; i++) {
        for (int j = 0; j < 5; j++) {
            hitCounter.hit(currentTimestamp + i * 1000);
        }
    }
    long latestTimeStamp = currentTimestamp + (timeInSec - 1) * 1000;
    Assert.assertNotNull(hitCounter);
    Assert.assertEquals(5, hitCounter.getMaxCountPerBucket(latestTimeStamp));
    // 2 seconds have passed, the hit counter should return 5 as well since the count in the last bucket could increase.
    latestTimeStamp = latestTimeStamp + 2000L;
    Assert.assertEquals(5, hitCounter.getMaxCountPerBucket(latestTimeStamp));
    // This time it should return 0 as the internal lastAccessTimestamp has already been updated and there is no more hits between the gap.
    latestTimeStamp = latestTimeStamp + 2000L;
    Assert.assertEquals(0, hitCounter.getMaxCountPerBucket(latestTimeStamp));
    // Increment the hit in this second and we should see the result becomes 1.
    hitCounter.hit(latestTimeStamp);
    latestTimeStamp = latestTimeStamp + 2000L;
    Assert.assertEquals(1, hitCounter.getMaxCountPerBucket(latestTimeStamp));
    // More than a time range period has passed and the hit counter should return 0 as there is no hits.
    hitCounter.hit(latestTimeStamp);
    latestTimeStamp = latestTimeStamp + timeInSec * 2 * 1000L + 2000L;
    Assert.assertEquals(0, hitCounter.getMaxCountPerBucket(latestTimeStamp));
}

@Test
public void testSinglePqlAndSqlCompatible() {
    final String sql = "SELECT CarrierDelay, Origin, DayOfWeek FROM mytable WHERE ActualElapsedTime BETWEEN 163 AND 322 OR CarrierDelay IN (17, 266) OR AirlineID IN (19690, 20366) ORDER BY TaxiIn, TailNum LIMIT 1";
    final String pql = "SELECT CarrierDelay, Origin, DayOfWeek FROM mytable WHERE ActualElapsedTime BETWEEN 163 AND 322 OR CarrierDelay IN (17, 266) OR AirlineID IN (19690, 20366) ORDER BY TaxiIn, TailNum LIMIT 1";
    // PQL
    LOGGER.info("Trying to compile PQL: {}", pql);
    // NOTE: SQL is always using upper cases, so we need to make the string to upper case in order to match the parsed identifier name.
    final BrokerRequest unOptimizedBrokerRequestFromPQL = COMPILER.compileToBrokerRequest(pql);
    final BrokerRequest brokerRequestFromPQL = OPTIMIZER.optimize(unOptimizedBrokerRequestFromPQL, null);
    LOGGER.debug("Compiled PQL: PQL: {}, BrokerRequest: {}", pql, brokerRequestFromPQL);
    brokerRequestFromPQL.unsetPinotQuery();
    //SQL
    LOGGER.info("Trying to compile SQL: {}", sql);
    final PinotQuery pinotQuery = CalciteSqlParser.compileToPinotQuery(sql);
    final BrokerRequest brokerRequestFromSQL = OPTIMIZER.optimize(new PinotQuery2BrokerRequestConverter().convert(pinotQuery), null);
    LOGGER.debug("Compiled SQL: SQL: {}, PinotQuery: {}, BrokerRequest: {}", sql, pinotQuery, brokerRequestFromSQL);
    // Compare
    LOGGER.info("Trying to compare BrokerRequest -\nFrom PQL: {}\nFrom SQL: {}", brokerRequestFromPQL, brokerRequestFromSQL);
    Assert.assertTrue(BrokerRequestComparisonUtils.validate(brokerRequestFromPQL, brokerRequestFromSQL));
}

