public void testConverter() throws IOException {
    COMPILER.compileToBrokerRequest("Select * from T where a IN (1,2,2,3,4)");
    COMPILER.compileToBrokerRequest("SELECT MIN(div(DaysSinceEpoch,2)) FROM mytable");
    COMPILER.compileToBrokerRequest("SELECT SUM(DepDelayMinutes), SUM(ArrDel15), SUM(DepDelay), SUM(DepDel15) FROM myStarTable WHERE Carrier IN ('UA', 'WN', 'FL', 'F9') AND Carrier NOT IN ('EV', 'AS', 'FL') AND DayofMonth > 5 AND DayofMonth <= 17 AND Diverted > 0 AND OriginCityName > 'Detroit, MI' GROUP BY CRSDepTime");
    COMPILER.compileToBrokerRequest("Select * from T where a > 1 and a < 10");
    COMPILER.compileToBrokerRequest("Select * from T where a between 1 and 10");
    BrokerRequest brokerRequest = COMPILER.compileToBrokerRequest("select * from vegetables where name != 'Brussels sprouts'");
    Assert.assertEquals(brokerRequest.getPinotQuery().getFilterExpression().getFunctionCall().getOperator(), FilterKind.NOT_EQUALS.name());
    final BufferedReader br = new BufferedReader(new InputStreamReader(Pql2CompilerTest.class.getClassLoader().getResourceAsStream("pql_queries.list")));
    String pql;
    int seqId = 0;
    while ((pql = br.readLine()) != null) {
        try {
            LOGGER.info("Trying to compile PQL Id - {}, PQL: {}", seqId++, pql);
            COMPILER.compileToBrokerRequest(pql);
        } catch (Exception e) {
            LOGGER.error("Failed to compile pql {} to BrokerRequest.", pql, e);
            throw e;
        }
    }
}

