@Test
public void testFlattenAndOr() {
    {
        String query = "SELECT * FROM foo WHERE col1 > 0 AND (col2 > 0 AND col3 > 0) AND col4 > 0";
        PinotQuery pinotQuery = CalciteSqlParser.compileToPinotQuery(query);
