@Test
public void testSegmentLineageCleanup() throws IOException, InterruptedException {
    // Create metadata for original segments
    for (int i = 0; i < 5; ++i) {
        _helixResourceManager.addNewSegment(OFFLINE_TABLE_NAME, SegmentMetadataMockUtils.mockSegmentMetadata(OFFLINE_TABLE_NAME, "segment_" + i), "downloadUrl");
    }
    // Create metadata for merged segments.
    for (int i = 0; i < 2; ++i) {
        _helixResourceManager.addNewSegment(OFFLINE_TABLE_NAME, SegmentMetadataMockUtils.mockSegmentMetadata(OFFLINE_TABLE_NAME, "merged_" + i), "downloadUrl");
    }
    Assert.assertEquals(_helixResourceManager.getSegmentsFor(OFFLINE_TABLE_NAME).size(), 7);
    long currentTimeInMillis = System.currentTimeMillis();
    // Validate the case when the lineage entry state is 'IN_PROGRESS'
    SegmentLineage segmentLineage = new SegmentLineage(OFFLINE_TABLE_NAME);
    segmentLineage.addLineageEntry("0", new LineageEntry(Arrays.asList("segment_0", "segment_1"), Arrays.asList("merged_0"), LineageEntryState.IN_PROGRESS, currentTimeInMillis));
    SegmentLineageAccessHelper.writeSegmentLineage(_helixResourceManager.getPropertyStore(), segmentLineage, -1);
    _retentionManager.processTable(OFFLINE_TABLE_NAME);
    waitForSegmentsToDelete(OFFLINE_TABLE_NAME, 7);
    List<String> segmentsForTable = _helixResourceManager.getSegmentsFor(OFFLINE_TABLE_NAME);
    Assert.assertEquals(segmentsForTable.size(), 7);
    // Validate the case when the lineage entry state is 'COMPLETED'
    segmentLineage.updateLineageEntry("0", new LineageEntry(Arrays.asList("segment_0", "segment_1"), Arrays.asList("merged_0"), LineageEntryState.COMPLETED, currentTimeInMillis));
    SegmentLineageAccessHelper.writeSegmentLineage(_helixResourceManager.getPropertyStore(), segmentLineage, -1);
    _retentionManager.processTable(OFFLINE_TABLE_NAME);
    waitForSegmentsToDelete(OFFLINE_TABLE_NAME, 5);
    segmentsForTable = _helixResourceManager.getSegmentsFor(OFFLINE_TABLE_NAME);
    Assert.assertEquals(segmentsForTable.size(), 5);
    Assert.assertTrue(Collections.disjoint(segmentsForTable, Arrays.asList("segment_0", "segment_1")));
    // Validate the case when the lineage entry state is 'COMPLETED' and all segments are deleted
    _helixResourceManager.deleteSegment(OFFLINE_TABLE_NAME, "merged_0");
    waitForSegmentsToDelete(OFFLINE_TABLE_NAME, 4);
    _retentionManager.processTable(OFFLINE_TABLE_NAME);
    waitForSegmentsToDelete(OFFLINE_TABLE_NAME, 4);
    segmentsForTable = _helixResourceManager.getSegmentsFor(OFFLINE_TABLE_NAME);
    Assert.assertEquals(segmentsForTable.size(), 4);
    Assert.assertTrue(Collections.disjoint(segmentsForTable, Arrays.asList("segment_0", "segment_1", "merged_0")));
    segmentLineage = SegmentLineageAccessHelper.getSegmentLineage(_helixResourceManager.getPropertyStore(), OFFLINE_TABLE_NAME);
    Assert.assertEquals(segmentLineage.getLineageEntryIds().size(), 0);
    // Validate the case when the lineage entry state is 'IN_PROGRESS' and timestamp is old
    LineageEntry lineageEntry = new LineageEntry(Arrays.asList("segment_2", "segment_3"), Arrays.asList("merged_1", "merged_2"), LineageEntryState.IN_PROGRESS, currentTimeInMillis - TimeUnit.DAYS.toMillis(2L));
    segmentLineage.addLineageEntry("1", lineageEntry);
    SegmentLineageAccessHelper.writeSegmentLineage(_helixResourceManager.getPropertyStore(), segmentLineage, -1);
    _retentionManager.processTable(OFFLINE_TABLE_NAME);
    waitForSegmentsToDelete(OFFLINE_TABLE_NAME, 3);
    segmentsForTable = _helixResourceManager.getSegmentsFor(OFFLINE_TABLE_NAME);
    Assert.assertEquals(segmentsForTable.size(), 3);
    Assert.assertTrue(Collections.disjoint(segmentsForTable, Arrays.asList("merged_1", "merged_2")));
    segmentLineage = SegmentLineageAccessHelper.getSegmentLineage(_helixResourceManager.getPropertyStore(), OFFLINE_TABLE_NAME);
    Assert.assertEquals(segmentLineage.getLineageEntryIds().size(), 1);
}

@Test
public void testTimeRetention() {
    String tableNameWithType = "myTable_OFFLINE";
    TimeRetentionStrategy retentionStrategy = new TimeRetentionStrategy(TimeUnit.DAYS, 30L);
    SegmentZKMetadata metadata = new OfflineSegmentZKMetadata();
    // Without setting time unit or end time, should not throw exception
    assertFalse(retentionStrategy.isPurgeable(tableNameWithType, metadata));
    metadata.setTimeUnit(TimeUnit.DAYS);
    assertFalse(retentionStrategy.isPurgeable(tableNameWithType, metadata));
    // Set end time to Jan 2nd, 1970 (not purgeable due to bogus timestamp)
    metadata.setEndTime(1L);
    assertFalse(retentionStrategy.isPurgeable(tableNameWithType, metadata));
    // Set end time to today
    long today = TimeUnit.MILLISECONDS.toDays(System.currentTimeMillis());
    metadata.setEndTime(today);
    assertFalse(retentionStrategy.isPurgeable(tableNameWithType, metadata));
    // Set end time to two weeks ago
    metadata.setEndTime(today - 14);
    assertFalse(retentionStrategy.isPurgeable(tableNameWithType, metadata));
    // Set end time to two months ago (purgeable due to being past the retention period)
    metadata.setEndTime(today - 60);
    assertTrue(retentionStrategy.isPurgeable(tableNameWithType, metadata));
    // Set end time to 200 years in the future (not purgeable due to bogus timestamp)
    metadata.setEndTime(today + (365 * 200));
    assertFalse(retentionStrategy.isPurgeable(tableNameWithType, metadata));
}

