public void testRemoveDeletedSegments() throws Exception {
    Map<String, Object> properties = new HashMap<>();
    properties.put(CommonConstants.Controller.PREFIX_OF_CONFIG_OF_PINOT_FS_FACTORY + ".class", LocalPinotFS.class.getName());
    PinotFSFactory.init(new PinotConfiguration(properties));
