@Test
public void testCommitAfterCatchup() throws Exception {
    FakeLLRealtimeSegmentDataManager segmentDataManager = createFakeSegmentManager();
    LLRealtimeSegmentDataManager.PartitionConsumer consumer = segmentDataManager.createPartitionConsumer();
    final LongMsgOffset firstOffset = new LongMsgOffset(_startOffsetValue + 500);
    final LongMsgOffset catchupOffset = new LongMsgOffset(firstOffset.getOffset() + 10);
    // We should consume initially...
    segmentDataManager._consumeOffsets.add(firstOffset);
    // Offset after catchup
    segmentDataManager._consumeOffsets.add(catchupOffset);
    final SegmentCompletionProtocol.Response holdResponse1 = new SegmentCompletionProtocol.Response(new SegmentCompletionProtocol.Response.Params().withStatus(SegmentCompletionProtocol.ControllerResponseStatus.HOLD).withStreamPartitionMsgOffset(firstOffset.toString()));
    final SegmentCompletionProtocol.Response catchupResponse = new SegmentCompletionProtocol.Response(new SegmentCompletionProtocol.Response.Params().withStatus(SegmentCompletionProtocol.ControllerResponseStatus.CATCH_UP).withStreamPartitionMsgOffset(catchupOffset.toString()));
    final SegmentCompletionProtocol.Response holdResponse2 = new SegmentCompletionProtocol.Response(new SegmentCompletionProtocol.Response.Params().withStreamPartitionMsgOffset(catchupOffset.toString()).withStatus(SegmentCompletionProtocol.ControllerResponseStatus.HOLD));
