@Test
public void testStandardize() {
    /**
     * Tests for Map
     */
    // Empty Map
    Map<String, Object> map = Collections.emptyMap();
    assertNull(DataTypeTransformer.standardize(COLUMN, map, true));
    assertNull(DataTypeTransformer.standardize(COLUMN, map, false));
    // Map with single entry
    String expectedValue = "testValue";
    map = Collections.singletonMap("testKey", expectedValue);
    assertEquals(DataTypeTransformer.standardize(COLUMN, map, true), expectedValue);
    assertEquals(DataTypeTransformer.standardize(COLUMN, map, false), expectedValue);
    // Map with multiple entries
    Object[] expectedValues = new Object[] { "testValue1", "testValue2" };
    map = new HashMap<>();
    map.put("testKey1", "testValue1");
    map.put("testKey2", "testValue2");
    try {
        // Should fail because Map with multiple entries cannot be standardized as single value
        DataTypeTransformer.standardize(COLUMN, map, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEqualsNoOrder((Object[]) DataTypeTransformer.standardize(COLUMN, map, false), expectedValues);
    /**
     * Tests for List
     */
    // Empty List
    List<Object> list = Collections.emptyList();
    assertNull(DataTypeTransformer.standardize(COLUMN, list, true));
    assertNull(DataTypeTransformer.standardize(COLUMN, list, false));
    // List with single entry
    list = Collections.singletonList(expectedValue);
    assertEquals(DataTypeTransformer.standardize(COLUMN, list, true), expectedValue);
    assertEquals(DataTypeTransformer.standardize(COLUMN, list, false), expectedValue);
    // List with multiple entries
    list = Arrays.asList(expectedValues);
    try {
        // Should fail because List with multiple entries cannot be standardized as single value
        DataTypeTransformer.standardize(COLUMN, list, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEquals((Object[]) DataTypeTransformer.standardize(COLUMN, list, false), expectedValues);
    /**
     * Tests for Object[]
     */
    // Empty Object[]
    Object[] values = new Object[0];
    assertNull(DataTypeTransformer.standardize(COLUMN, values, true));
    assertNull(DataTypeTransformer.standardize(COLUMN, values, false));
    // Object[] with single entry
    values = new Object[] { expectedValue };
    assertEquals(DataTypeTransformer.standardize(COLUMN, values, true), expectedValue);
    assertEquals(DataTypeTransformer.standardize(COLUMN, values, false), expectedValue);
    // Object[] with multiple entries
    values = new Object[] { "testValue1", "testValue2" };
    try {
        // Should fail because Object[] with multiple entries cannot be standardized as single value
        DataTypeTransformer.standardize(COLUMN, values, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEquals((Object[]) DataTypeTransformer.standardize(COLUMN, values, false), expectedValues);
    /**
     * Tests for nested Map/List/Object[]
     */
    // Map with empty List
    map = Collections.singletonMap("testKey", Collections.emptyList());
    assertNull(DataTypeTransformer.standardize(COLUMN, map, true));
    assertNull(DataTypeTransformer.standardize(COLUMN, map, false));
    // Map with single-entry List
    map = Collections.singletonMap("testKey", Collections.singletonList(expectedValue));
    assertEquals(DataTypeTransformer.standardize(COLUMN, map, true), expectedValue);
    assertEquals(DataTypeTransformer.standardize(COLUMN, map, false), expectedValue);
    // Map with one empty Map and one single-entry Map
    map = new HashMap<>();
    map.put("testKey1", Collections.emptyMap());
    map.put("testKey2", Collections.singletonMap("testKey", expectedValue));
    // Can be standardized into single value because empty Map should be ignored
    assertEquals(DataTypeTransformer.standardize(COLUMN, map, true), expectedValue);
    assertEquals(DataTypeTransformer.standardize(COLUMN, map, false), expectedValue);
    // Map with multi-entries List
    map = Collections.singletonMap("testKey", Arrays.asList(expectedValues));
    try {
        // Should fail because Map with multiple entries cannot be standardized as single value
        DataTypeTransformer.standardize(COLUMN, map, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEqualsNoOrder((Object[]) DataTypeTransformer.standardize(COLUMN, map, false), expectedValues);
    // Map with one empty Map, one single-entry List and one single-entry Object[]
    map = new HashMap<>();
    map.put("testKey1", Collections.emptyMap());
    map.put("testKey2", Collections.singletonList("testValue1"));
    map.put("testKey3", new Object[] { "testValue2" });
    try {
        // Should fail because Map with multiple entries cannot be standardized as single value
        DataTypeTransformer.standardize(COLUMN, map, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEqualsNoOrder((Object[]) DataTypeTransformer.standardize(COLUMN, map, false), expectedValues);
    // List with two single-entry Maps and one empty Map
    list = Arrays.asList(Collections.singletonMap("testKey", "testValue1"), Collections.singletonMap("testKey", "testValue2"), Collections.emptyMap());
    try {
        // Should fail because List with multiple entries cannot be standardized as single value
        DataTypeTransformer.standardize(COLUMN, list, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEquals((Object[]) DataTypeTransformer.standardize(COLUMN, list, false), expectedValues);
    // Object[] with two single-entry Maps
    values = new Object[] { Collections.singletonMap("testKey", "testValue1"), Collections.singletonMap("testKey", "testValue2") };
    try {
        // Should fail because Object[] with multiple entries cannot be standardized as single value
        DataTypeTransformer.standardize(COLUMN, values, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEqualsNoOrder((Object[]) DataTypeTransformer.standardize(COLUMN, values, false), expectedValues);
    // Object[] with one empty Object[], one multi-entries List of nested Map/List/Object[]
    values = new Object[] { new Object[0], Collections.singletonList(Collections.singletonMap("testKey", "testValue1")), Collections.singletonMap("testKey", Arrays.asList(new Object[] { "testValue2" }, Collections.emptyMap())) };
    try {
        DataTypeTransformer.standardize(COLUMN, values, true);
        fail();
    } catch (Exception e) {
        // Expected
    }
    assertEqualsNoOrder((Object[]) DataTypeTransformer.standardize(COLUMN, values, false), expectedValues);
}

@Test
public void testTransformConfigsFromTableConfig() {
    Schema pinotSchema = new Schema.SchemaBuilder().addSingleValueDimension("userId", FieldSpec.DataType.LONG).addSingleValueDimension("fullName", FieldSpec.DataType.STRING).addMultiValueDimension("bids", FieldSpec.DataType.INT).addSingleValueDimension("maxBid", FieldSpec.DataType.INT).addMultiValueDimension("map2_keys", FieldSpec.DataType.STRING).addMultiValueDimension("map2_values", FieldSpec.DataType.INT).addMetric("cost", FieldSpec.DataType.DOUBLE).addDateTime("hoursSinceEpoch", FieldSpec.DataType.LONG, "1:HOURS:EPOCH", "1:HOURS").build();
    List<TransformConfig> transformConfigs = new ArrayList<>();
    transformConfigs.add(new TransformConfig("userId", "Groovy({user_id}, user_id)"));
    transformConfigs.add(new TransformConfig("fullName", "Groovy({firstName+' '+lastName}, firstName, lastName)"));
    transformConfigs.add(new TransformConfig("maxBid", "Groovy({bids.max{ it.toBigDecimal() }}, bids)"));
    transformConfigs.add(new TransformConfig("map2_keys", "Groovy({map2.sort()*.key}, map2)"));
    transformConfigs.add(new TransformConfig("map2_values", "Groovy({map2.sort()*.value}, map2)"));
    transformConfigs.add(new TransformConfig("hoursSinceEpoch", "Groovy({timestamp/(1000*60*60)}, timestamp)"));
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("testTransformFunctions").setIngestionConfig(new IngestionConfig(null, transformConfigs)).build();
    ExpressionTransformer expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    DataTypeTransformer dataTypeTransformer = new DataTypeTransformer(pinotSchema);
    // test functions from schema
    GenericRow genericRow = new GenericRow();
    genericRow.putValue("user_id", 1L);
    genericRow.putValue("firstName", "John");
    genericRow.putValue("lastName", "Denver");
    genericRow.putValue("bids", Arrays.asList(10, 20));
    // keys in Map from avro are always in STRING
    HashMap<String, String> map1 = new HashMap<>();
    map1.put("30", "foo");
    map1.put("200", "bar");
    genericRow.putValue("map1", map1);
    HashMap<String, Integer> map2 = new HashMap<>();
    map2.put("k1", 10);
    map2.put("k2", 20);
    genericRow.putValue("map2", map2);
    genericRow.putValue("cost", 1000.0);
    genericRow.putValue("timestamp", 1574000000000L);
    genericRow.putValue("lon", 1.0);
    genericRow.putValue("lat", 2.0);
    // expression transformer
    expressionTransformer.transform(genericRow);
    // extract userId
    Assert.assertEquals(genericRow.getValue("userId"), 1L);
    // concat fullName
    Assert.assertEquals(genericRow.getValue("fullName"), "John Denver");
    Assert.assertTrue(((List) genericRow.getValue("bids")).containsAll(Arrays.asList(10, 20)));
    // find max bid from bids
    Assert.assertEquals(genericRow.getValue("maxBid"), 20);
    // handle Map through transform functions
    ArrayList map2__keys = (ArrayList) genericRow.getValue("map2_keys");
    Assert.assertEquals(map2__keys.get(0), "k1");
    Assert.assertEquals(map2__keys.get(1), "k2");
    ArrayList map2__values = (ArrayList) genericRow.getValue("map2_values");
    Assert.assertEquals(map2__values.get(0), 10);
    Assert.assertEquals(map2__values.get(1), 20);
    Assert.assertEquals(genericRow.getValue("cost"), 1000.0);
    // calculate hoursSinceEpoch
    Assert.assertEquals(genericRow.getValue("hoursSinceEpoch").toString(), "437222.2222222222");
    // data type transformer
    dataTypeTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("userId"), 1L);
    Assert.assertEquals(genericRow.getValue("fullName"), "John Denver");
    Assert.assertEquals(((Object[]) genericRow.getValue("bids")), new Integer[] { 10, 20 });
    Assert.assertEquals(genericRow.getValue("maxBid"), 20);
    // handle Map through transform functions
    Object[] map2Keys = (Object[]) genericRow.getValue("map2_keys");
    Assert.assertEquals(map2Keys[0], "k1");
    Assert.assertEquals(map2Keys[1], "k2");
    Object[] map2Values = (Object[]) genericRow.getValue("map2_values");
    Assert.assertEquals(map2Values[0], 10);
    Assert.assertEquals(map2Values[1], 20);
    Assert.assertEquals(genericRow.getValue("cost"), 1000.0);
    // convert to LONG
    Assert.assertEquals(genericRow.getValue("hoursSinceEpoch"), 437222L);
}

