    // only specified in schema
    pinotSchema.getFieldSpecFor("maxBid").setTransformFunction("Groovy({bids.max{ it.toBigDecimal() }}, bids)");
    // also specified in table config, ignore the schema setting
    pinotSchema.getFieldSpecFor("hoursSinceEpoch").setTransformFunction("Groovy({timestamp/(1000)}, timestamp)");
    List<TransformConfig> transformConfigs = new ArrayList<>();
    transformConfigs.add(new TransformConfig("userId", "Groovy({user_id}, user_id)"));
    transformConfigs.add(new TransformConfig("fullName", "Groovy({firstName+' '+lastName}, firstName, lastName)"));
    transformConfigs.add(new TransformConfig("hoursSinceEpoch", "Groovy({timestamp/(1000*60*60)}, timestamp)"));
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("testTransformFunctions").setIngestionConfig(new IngestionConfig(null, transformConfigs)).build();
    ExpressionTransformer expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    GenericRow genericRow = new GenericRow();
    genericRow.putValue("user_id", 1L);
    genericRow.putValue("firstName", "John");
    genericRow.putValue("lastName", "Denver");
    genericRow.putValue("bids", Arrays.asList(10, 20));
    // keys in Map from avro are always in STRING
    HashMap<String, String> map1 = new HashMap<>();
    map1.put("30", "foo");
    map1.put("200", "bar");
    genericRow.putValue("map1", map1);
    HashMap<String, Integer> map2 = new HashMap<>();
    map2.put("k1", 10);
    map2.put("k2", 20);
    genericRow.putValue("map2", map2);
    genericRow.putValue("cost", 1000.0);
    genericRow.putValue("timestamp", 1574000000000L);
    // expression transformer
    expressionTransformer.transform(genericRow);
    // extract userId
    Assert.assertEquals(genericRow.getValue("userId"), 1L);
    // concat fullName
    Assert.assertEquals(genericRow.getValue("fullName"), "John Denver");
    Assert.assertTrue(((List) genericRow.getValue("bids")).containsAll(Arrays.asList(10, 20)));
    // find max bid from bids
    Assert.assertEquals(genericRow.getValue("maxBid"), 20);
    // Backward compatible way to support MAP - __KEYS indicates keys of map1
    ArrayList map1__keys = (ArrayList) genericRow.getValue("map1__KEYS");
    Assert.assertEquals(map1__keys.get(0), "200");
    Assert.assertEquals(map1__keys.get(1), "30");
    // Backward compatible way to support MAP - __VALUES indicates values of map1
    ArrayList map1__values = (ArrayList) genericRow.getValue("map1__VALUES");
    Assert.assertEquals(map1__values.get(0), "bar");
    Assert.assertEquals(map1__values.get(1), "foo");
    Assert.assertEquals(genericRow.getValue("cost"), 1000.0);
    // calculate hoursSinceEpoch
    Assert.assertEquals(genericRow.getValue("hoursSinceEpoch").toString(), "437222.2222222222");
}

/**
 * If destination field already exists in the row, do not execute transform function
 */
@Test
public void testValueAlreadyExists() {
    Schema pinotSchema = new Schema();
    DimensionFieldSpec dimensionFieldSpec = new DimensionFieldSpec("fullName", FieldSpec.DataType.STRING, true);
    pinotSchema.addField(dimensionFieldSpec);
    List<TransformConfig> transformConfigs = new ArrayList<>();
    transformConfigs.add(new TransformConfig("fullName", "Groovy({firstName + ' ' + lastName}, firstName, lastName)"));
    TableConfig tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName("testValueExists").setIngestionConfig(new IngestionConfig(null, transformConfigs)).build();
    ExpressionTransformer expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    GenericRow genericRow = new GenericRow();
    genericRow.putValue("firstName", "John");
    genericRow.putValue("lastName", "Denver");
    genericRow.putValue("fullName", "John N Denver");
    // no transformation
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("fullName"), "John N Denver");
    pinotSchema = new Schema.SchemaBuilder().addTime(new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.MILLISECONDS, "incoming"), new TimeGranularitySpec(FieldSpec.DataType.INT, TimeUnit.DAYS, "outgoing")).build();
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName("testValueExists").setIngestionConfig(new IngestionConfig(null, null)).build();
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", "123456789");
    genericRow.putValue("outgoing", "123");
    // no transformation
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), "123");
}

@Test
public void testTimeSpecConversion() {
    long validMillis = 1585724400000L;
    long validHours = 440479;
    ExpressionTransformer expressionTransformer;
    // all combinations of timespec, and values in the incoming outgoing
    Schema pinotSchema;
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("testTimeSpecTransformer").build();
    // 1] only incoming defined - doesn't create DefaultTimeSpecEvaluator. Incoming value used as is.
    pinotSchema = new Schema.SchemaBuilder().addTime(new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.MILLISECONDS, "incoming"), null).build();
    // correct value for incoming - use incoming
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    GenericRow genericRow = new GenericRow();
    genericRow.putValue("incoming", validMillis);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("incoming"), validMillis);
    // incorrect value - use whatever is
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", -1);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("incoming"), -1);
    // 2] both incoming and outgoing defined - exactly the same - Doesn't create DefaultTimeFSpecEvaluator, incoming used as is.
    pinotSchema = new Schema.SchemaBuilder().addTime(new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.MILLISECONDS, "time"), new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.MILLISECONDS, "time")).build();
    // correct value - use incoming
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("time", validMillis);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("time"), validMillis);
    // incorrect value - use whatever is
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("time", -1);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("time"), -1);
    // 3] both incoming and outgoing defined - same column name only - skip conversion - this shouldn't be allowed by validation during add schema
    try {
        pinotSchema = new Schema.SchemaBuilder().addTime(new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.MILLISECONDS, "time"), new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.HOURS, "time")).build();
        new ExpressionTransformer(tableConfig, pinotSchema);
        Assert.fail();
    } catch (Exception e) {
        // expected
    }
    // 4] both incoming and outgoing defined - different column names - convert when possible
    pinotSchema = new Schema.SchemaBuilder().addTime(new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.MILLISECONDS, "incoming"), new TimeGranularitySpec(FieldSpec.DataType.LONG, TimeUnit.HOURS, "outgoing")).build();
    // only valid incoming value exists - convert using DefaultTimeSpecEvaluator
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", validMillis);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), validHours);
    // only valid outgoing value exists - Never invokes transformation using DefaultTimeSpecEvaluator, as outgoing already present
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("outgoing", validHours);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), validHours);
    // only invalid incoming value exists - exception when validating
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", -1);
    try {
        expressionTransformer.transform(genericRow);
        Assert.fail();
    } catch (Exception e) {
        // expected
    }
    // only invalid outgoing value exists - Never invokes transformation using DefaultTimeSpecEvaluator, as outgoing already present
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("outgoing", -1);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), -1);
    // both valid incoming and outgoing exist - Never invokes transformation using DefaultTimeSpecEvaluator, as outgoing already present
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", validMillis);
    genericRow.putValue("outgoing", validHours);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), validHours);
    // invalid incoming, valid outgoing - Never invokes transformation using DefaultTimeSpecEvaluator, as outgoing already present
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", -1);
    genericRow.putValue("outgoing", validHours);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), validHours);
    // valid incoming, invalid outgoing - Never invokes transformation using DefaultTimeSpecEvaluator, as outgoing already present
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", validMillis);
    genericRow.putValue("outgoing", -1);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), -1);
    // invalid incoming and outgoing - Never invokes transformation using DefaultTimeSpecEvaluator, as outgoing already present
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("incoming", -1);
    genericRow.putValue("outgoing", -1);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("outgoing"), -1);
    // 5] SIMPLE_DATE_FORMAT
    // When incoming and outgoing spec are the same, any time format should work
    pinotSchema = new Schema.SchemaBuilder().addTime(new TimeGranularitySpec(FieldSpec.DataType.INT, TimeUnit.DAYS, TimeGranularitySpec.TimeFormat.SIMPLE_DATE_FORMAT.toString(), "time"), null).build();
    expressionTransformer = new ExpressionTransformer(tableConfig, pinotSchema);
    genericRow = new GenericRow();
    genericRow.putValue("time", 20180101);
    expressionTransformer.transform(genericRow);
    Assert.assertEquals(genericRow.getValue("time"), 20180101);
}

@Test
public void testFilterTransformer() {
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName("testTable").build();
    // expression false, not filtered
    GenericRow genericRow = getRecord();
    tableConfig.setIngestionConfig(new IngestionConfig(new FilterConfig("Groovy({svInt > 123}, svInt)"), null));
    RecordTransformer transformer = new FilterTransformer(tableConfig);
    transformer.transform(genericRow);
    Assert.assertFalse(genericRow.getFieldToValueMap().containsKey(GenericRow.SKIP_RECORD_KEY));
    // expression true, filtered
    genericRow = getRecord();
    tableConfig.setIngestionConfig(new IngestionConfig(new FilterConfig("Groovy({svInt <= 123}, svInt)"), null));
    transformer = new FilterTransformer(tableConfig);
    transformer.transform(genericRow);
    Assert.assertTrue(genericRow.getFieldToValueMap().containsKey(GenericRow.SKIP_RECORD_KEY));
    // value not found
    genericRow = getRecord();
    tableConfig.setIngestionConfig(new IngestionConfig(new FilterConfig("Groovy({notPresent == 123}, notPresent)"), null));
    transformer = new FilterTransformer(tableConfig);
    transformer.transform(genericRow);
    Assert.assertFalse(genericRow.getFieldToValueMap().containsKey(GenericRow.SKIP_RECORD_KEY));
    // invalid function
    tableConfig.setIngestionConfig(new IngestionConfig(new FilterConfig("Groovy(svInt == 123)"), null));
    try {
        new FilterTransformer(tableConfig);
        Assert.fail("Should have failed constructing FilterTransformer");
    } catch (Exception e) {
        // expected
    }
    // multi value column
    genericRow = getRecord();
    tableConfig.setIngestionConfig(new IngestionConfig(new FilterConfig("Groovy({svFloat.max() < 500}, svFloat)"), null));
    transformer = new FilterTransformer(tableConfig);
    transformer.transform(genericRow);
    Assert.assertTrue(genericRow.getFieldToValueMap().containsKey(GenericRow.SKIP_RECORD_KEY));
}

