@Test
public void testAggregateMetrics() {
    Schema schema = new Schema.SchemaBuilder().setSchemaName("testSchema").addSingleValueDimension(DIMENSION_1, FieldSpec.DataType.INT).addSingleValueDimension(DIMENSION_2, FieldSpec.DataType.STRING).addMetric(METRIC, FieldSpec.DataType.LONG).addMetric(METRIC_2, FieldSpec.DataType.FLOAT).addTime(new TimeGranularitySpec(FieldSpec.DataType.INT, TimeUnit.DAYS, TIME_COLUMN1), null).addDateTime(TIME_COLUMN2, FieldSpec.DataType.INT, "1:HOURS:EPOCH", "1:HOURS").build();
    // Add virtual columns, which should not be aggregated
    DimensionFieldSpec virtualDimensionFieldSpec = new DimensionFieldSpec("$virtualDimension", FieldSpec.DataType.INT, true, Object.class);
    schema.addField(virtualDimensionFieldSpec);
    MetricFieldSpec virtualMetricFieldSpec = new MetricFieldSpec("$virtualMetric", FieldSpec.DataType.INT);
    virtualMetricFieldSpec.setVirtualColumnProvider("provider.class");
    schema.addField(virtualMetricFieldSpec);
    MutableSegmentImpl mutableSegmentImpl = MutableSegmentImplTestUtils.createMutableSegmentImpl(schema, new HashSet<>(Arrays.asList(METRIC, METRIC_2)), Collections.singleton(DIMENSION_2), new HashSet<>(Arrays.asList(DIMENSION_1, DIMENSION_2, TIME_COLUMN1, TIME_COLUMN2)), true);
    testAggregateMetrics(mutableSegmentImpl);
    mutableSegmentImpl.destroy();
    schema = new Schema.SchemaBuilder().setSchemaName("testSchema").addSingleValueDimension(DIMENSION_1, FieldSpec.DataType.INT).addSingleValueDimension(DIMENSION_2, FieldSpec.DataType.STRING).addMetric(METRIC, FieldSpec.DataType.LONG).addMetric(METRIC_2, FieldSpec.DataType.FLOAT).addDateTime(TIME_COLUMN1, FieldSpec.DataType.INT, "1:DAYS:EPOCH", "1:DAYS").addDateTime(TIME_COLUMN2, FieldSpec.DataType.INT, "1:HOURS:EPOCH", "1:HOURS").build();
    // Add virtual columns, which should not be aggregated
    schema.addField(virtualDimensionFieldSpec);
    schema.addField(virtualMetricFieldSpec);
    mutableSegmentImpl = MutableSegmentImplTestUtils.createMutableSegmentImpl(schema, new HashSet<>(Arrays.asList(METRIC, METRIC_2)), Collections.singleton(DIMENSION_2), new HashSet<>(Arrays.asList(DIMENSION_1, DIMENSION_2, TIME_COLUMN1, TIME_COLUMN2)), true);
    testAggregateMetrics(mutableSegmentImpl);
    mutableSegmentImpl.destroy();
}

