        Assert.assertEquals(numPlans, count.get());
    }
}

@Test
public void testSlowPlanNode() {
    AtomicBoolean notInterrupted = new AtomicBoolean();
    List<PlanNode> planNodes = new ArrayList<>();
    for (int i = 0; i < 20; i++) {
        planNodes.add(() -> {
            try {
                Thread.sleep(10000);
            } catch (InterruptedException e) {
                // Thread should be interrupted
                throw new RuntimeException(e);
            }
            notInterrupted.set(true);
            return null;
        });
    }
    CombinePlanNode combinePlanNode = new CombinePlanNode(planNodes, _queryContext, _executorService, System.currentTimeMillis() + 100, InstancePlanMakerImplV2.DEFAULT_NUM_GROUPS_LIMIT, null);
    try {
        combinePlanNode.run();
    } catch (RuntimeException e) {
        Assert.assertTrue(e.getCause() instanceof TimeoutException);
        Assert.assertFalse(notInterrupted.get());
        return;
    }
    // Fail.
    Assert.fail();
}

