    result = _segmentPruner.prune(indexSegments, queryContext);
    assertEquals(result.size(), 3);
}

@Test
public void testHavingFilter() {
    // Simple having
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT COUNT(*) FROM testTable GROUP BY d1 HAVING COUNT(*) > 5");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "count(*)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler);
        assertFalse(havingFilterHandler.isMatch(new Object[] { 1, 5L }));
        assertTrue(havingFilterHandler.isMatch(new Object[] { 2, 10L }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 3, 3L }));
    }
    // Nested having
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT MAX(m1), MIN(m1) FROM testTable GROUP BY d1 HAVING MAX(m1) IN (15, 20, 25) AND (MIN(m1) > 10 OR MIN(m1) <= 3)");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "max(m1)", "min(m1)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler);
        assertFalse(havingFilterHandler.isMatch(new Object[] { 1, 15.5, 13.0 }));
        assertTrue(havingFilterHandler.isMatch(new Object[] { 2, 15.0, 3.0 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 3, 20.0, 7.5 }));
    }
    // Having with post-aggregation
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT MAX(m1), MIN(m2) FROM testTable GROUP BY d1 HAVING MAX(m1) > MIN(m2) * 2");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "max(m1)", "min(m2)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler);
        assertFalse(havingFilterHandler.isMatch(new Object[] { 1, 15.5, 13.0 }));
        assertTrue(havingFilterHandler.isMatch(new Object[] { 2, 15.0, 3.0 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 3, 20.0, 10.0 }));
    }
    // Having with all data types
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT COUNT(*) FROM testTable GROUP BY d1, d2, d3, d4, d5, d6 HAVING d1 > 10 AND d2 > 10 AND d3 > 10 AND d4 > 10 AND d5 > 10 AND d6 > 10");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "d2", "d3", "d4", "d5", "d6", "count(*)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.FLOAT, ColumnDataType.DOUBLE, ColumnDataType.STRING, ColumnDataType.BYTES, ColumnDataType.LONG });
        PostAggregationHandler postAggregationHandler = new PostAggregationHandler(queryContext, dataSchema);
        HavingFilterHandler havingFilterHandler = new HavingFilterHandler(queryContext.getHavingFilter(), postAggregationHandler);
        assertTrue(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.5, "11", new ByteArray(new byte[] { 17 }), 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 10, 11L, 10.5f, 10.5, "11", new ByteArray(new byte[] { 17 }), 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 10L, 10.5f, 10.5, "11", new ByteArray(new byte[] { 17 }), 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.0f, 10.5, "11", new ByteArray(new byte[] { 17 }), 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.0, "11", new ByteArray(new byte[] { 17 }), 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.5, "10", new ByteArray(new byte[] { 17 }), 5 }));
        assertFalse(havingFilterHandler.isMatch(new Object[] { 11, 11L, 10.5f, 10.5, "11", new ByteArray(new byte[] { 16 }), 5 }));
    }
}

@Test
public void testPostAggregation() {
    // Regular aggregation only
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT SUM(m1) FROM testTable");
        DataSchema dataSchema = new DataSchema(new String[] { "sum(m1)" }, new ColumnDataType[] { ColumnDataType.DOUBLE });
        PostAggregationHandler handler = new PostAggregationHandler(queryContext, dataSchema);
        assertEquals(handler.getResultDataSchema(), dataSchema);
        assertEquals(handler.getResult(new Object[] { 1.0 }), new Object[] { 1.0 });
        assertEquals(handler.getResult(new Object[] { 2.0 }), new Object[] { 2.0 });
    }
    // Regular aggregation group-by
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT d1, SUM(m1) FROM testTable GROUP BY d1");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "sum(m1)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.DOUBLE });
        PostAggregationHandler handler = new PostAggregationHandler(queryContext, dataSchema);
        assertEquals(handler.getResultDataSchema(), dataSchema);
        assertEquals(handler.getResult(new Object[] { 1, 2.0 }), new Object[] { 1, 2.0 });
        assertEquals(handler.getResult(new Object[] { 3, 4.0 }), new Object[] { 3, 4.0 });
    }
    // Aggregation group-by with partial columns selected
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT SUM(m1), d2 FROM testTable GROUP BY d1, d2");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "d2", "sum(m1)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE });
        PostAggregationHandler handler = new PostAggregationHandler(queryContext, dataSchema);
        DataSchema resultDataSchema = handler.getResultDataSchema();
        assertEquals(resultDataSchema.size(), 2);
        assertEquals(resultDataSchema.getColumnNames(), new String[] { "sum(m1)", "d2" });
        assertEquals(resultDataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.LONG });
        assertEquals(handler.getResult(new Object[] { 1, 2L, 3.0 }), new Object[] { 3.0, 2L });
        assertEquals(handler.getResult(new Object[] { 4, 5L, 6.0 }), new Object[] { 6.0, 5L });
    }
    // Aggregation group-by with order-by
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT SUM(m1), d2 FROM testTable GROUP BY d1, d2 ORDER BY MAX(m1)");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "d2", "sum(m1)", "max(m1)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
        PostAggregationHandler handler = new PostAggregationHandler(queryContext, dataSchema);
        DataSchema resultDataSchema = handler.getResultDataSchema();
        assertEquals(resultDataSchema.size(), 2);
        assertEquals(resultDataSchema.getColumnNames(), new String[] { "sum(m1)", "d2" });
        assertEquals(resultDataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.LONG });
        assertEquals(handler.getResult(new Object[] { 1, 2L, 3.0, 4.0 }), new Object[] { 3.0, 2L });
        assertEquals(handler.getResult(new Object[] { 5, 6L, 7.0, 8.0 }), new Object[] { 7.0, 6L });
    }
    // Post aggregation
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT SUM(m1) + MAX(m2) FROM testTable");
        DataSchema dataSchema = new DataSchema(new String[] { "sum(m1)", "max(m2)" }, new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
        PostAggregationHandler handler = new PostAggregationHandler(queryContext, dataSchema);
        DataSchema resultDataSchema = handler.getResultDataSchema();
        assertEquals(resultDataSchema.size(), 1);
        assertEquals(resultDataSchema.getColumnName(0), "plus(sum(m1),max(m2))");
        assertEquals(resultDataSchema.getColumnDataType(0), ColumnDataType.DOUBLE);
        assertEquals(handler.getResult(new Object[] { 1.0, 2.0 }), new Object[] { 3.0 });
        assertEquals(handler.getResult(new Object[] { 3.0, 4.0 }), new Object[] { 7.0 });
    }
    // Post aggregation with group-by and order-by
    {
        QueryContext queryContext = QueryContextConverterUtils.getQueryContextFromSQL("SELECT (SUM(m1) + MAX(m2) - d1) / 2, d2 FROM testTable GROUP BY d1, d2 ORDER BY MAX(m1)");
        DataSchema dataSchema = new DataSchema(new String[] { "d1", "d2", "sum(m1)", "max(m2)", "max(m1)" }, new ColumnDataType[] { ColumnDataType.INT, ColumnDataType.LONG, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE, ColumnDataType.DOUBLE });
        PostAggregationHandler handler = new PostAggregationHandler(queryContext, dataSchema);
        DataSchema resultDataSchema = handler.getResultDataSchema();
        assertEquals(resultDataSchema.size(), 2);
        assertEquals(resultDataSchema.getColumnNames(), new String[] { "divide(minus(plus(sum(m1),max(m2)),d1),'2')", "d2" });
        assertEquals(resultDataSchema.getColumnDataTypes(), new ColumnDataType[] { ColumnDataType.DOUBLE, ColumnDataType.LONG });
        assertEquals(handler.getResult(new Object[] { 1, 2L, 3.0, 4.0, 5.0 }), new Object[] { 3.0, 2L });
        assertEquals(handler.getResult(new Object[] { 6, 7L, 8.0, 9.0, 10.0 }), new Object[] { 5.5, 7L });
    }
}

@Test
public void testSerDe() throws Exception {
    // EqPredicate
    assertEquals(testSerDe("foo\t= 123"), "foo = '123'");
    assertEquals(testSerDe("foo='123'"), "foo = '123'");
    // NotEqPredicate
    assertEquals(testSerDe("foo !=123"), "foo != '123'");
    assertEquals(testSerDe("foo <>\t123"), "foo != '123'");
    assertEquals(testSerDe("foo\t\t!= '123'"), "foo != '123'");
    assertEquals(testSerDe("foo<> '123'"), "foo != '123'");
    // InPredicate
    assertEquals(testSerDe("foo in (123, \t456,789)"), "foo IN ('123','456','789')");
    assertEquals(testSerDe("foo In (\t '123', '456',  '789')"), "foo IN ('123','456','789')");
    // NotInPredicate
    assertEquals(testSerDe("foo NOT in (123, \t456,789)"), "foo NOT IN ('123','456','789')");
    assertEquals(testSerDe("foo NoT In (\t '123', '456',  '789')"), "foo NOT IN ('123','456','789')");
    // RangePredicate
    assertEquals(testSerDe("foo >123"), "foo > '123'");
    assertEquals(testSerDe("foo >=\t'123'"), "foo >= '123'");
    assertEquals(testSerDe("foo< 123"), "foo < '123'");
    assertEquals(testSerDe("foo\t<= '123'"), "foo <= '123'");
    assertEquals(testSerDe("foo bEtWeEn 123 AnD 456"), "foo BETWEEN '123' AND '456'");
    // RegexpLikePredicate
    assertEquals(testSerDe("ReGexP_lIKe(foo,\t\t'bar')"), "regexp_like(foo,'bar')");
    // TextMatchPredicate
    assertEquals(testSerDe("TEXT_MATCH(foo\t ,\t'bar')"), "text_match(foo,'bar')");
    // IsNullPredicate
    assertEquals(testSerDe("foo\tis\tnull"), "foo IS NULL");
    // IsNotNullPredicate
    assertEquals(testSerDe("foo\tIS not\tNulL"), "foo IS NOT NULL");
    // Non-standard RangePredicate (merged ranges)
    RangePredicate rangePredicate = new RangePredicate(ExpressionContext.forIdentifier("foo"), true, "123", false, "456");
    String predicateExpression = rangePredicate.toString();
    assertEquals(predicateExpression, "(foo >= '123' AND foo < '456')");
    Expression thriftExpression = CalciteSqlParser.compileToExpression(predicateExpression);
    FilterContext filter = QueryContextConverterUtils.getFilter(thriftExpression);
    assertEquals(filter.getType(), FilterContext.Type.AND);
    List<FilterContext> children = filter.getChildren();
    assertEquals(children.size(), 2);
    assertEquals(children.get(0).toString(), "foo >= '123'");
    assertEquals(children.get(1).toString(), "foo < '456'");
}

@Test
public void testHardcodedQueries() {
    // Select *
    {
        String query = "SELECT * FROM testTable";
        QueryContext[] queryContexts = getQueryContexts(query, query);
        for (QueryContext queryContext : queryContexts) {
            assertEquals(queryContext.getTableName(), "testTable");
            List<ExpressionContext> selectExpressions = queryContext.getSelectExpressions();
            assertEquals(selectExpressions.size(), 1);
            assertEquals(selectExpressions.get(0), ExpressionContext.forIdentifier("*"));
            assertEquals(selectExpressions.get(0).toString(), "*");
            assertTrue(queryContext.getAliasMap().isEmpty());
            assertNull(queryContext.getFilter());
            assertNull(queryContext.getGroupByExpressions());
            assertNull(queryContext.getOrderByExpressions());
            assertNull(queryContext.getHavingFilter());
            assertEquals(queryContext.getLimit(), 10);
            assertEquals(queryContext.getOffset(), 0);
            assertTrue(queryContext.getColumns().isEmpty());
            assertFalse(QueryContextUtils.isAggregationQuery(queryContext));
        }
    }
    // Select COUNT(*)
    {
        String query = "SELECT COUNT(*) FROM testTable";
        QueryContext[] queryContexts = getQueryContexts(query, query);
        for (QueryContext queryContext : queryContexts) {
            assertEquals(queryContext.getTableName(), "testTable");
            List<ExpressionContext> selectExpressions = queryContext.getSelectExpressions();
            assertEquals(selectExpressions.size(), 1);
            assertEquals(selectExpressions.get(0), ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.AGGREGATION, "count", Collections.singletonList(ExpressionContext.forIdentifier("*")))));
            assertEquals(selectExpressions.get(0).toString(), "count(*)");
            assertTrue(queryContext.getAliasMap().isEmpty());
            assertNull(queryContext.getFilter());
            assertNull(queryContext.getGroupByExpressions());
            assertNull(queryContext.getOrderByExpressions());
            assertNull(queryContext.getHavingFilter());
            assertEquals(queryContext.getLimit(), 10);
            assertEquals(queryContext.getOffset(), 0);
            assertTrue(queryContext.getColumns().isEmpty());
            assertTrue(QueryContextUtils.isAggregationQuery(queryContext));
        }
    }
    // Order-by
    {
        String query = "SELECT foo, bar FROM testTable ORDER BY bar ASC, foo DESC LIMIT 50, 100";
        QueryContext[] queryContexts = getQueryContexts(query, query);
        for (QueryContext queryContext : queryContexts) {
            assertEquals(queryContext.getTableName(), "testTable");
            List<ExpressionContext> selectExpressions = queryContext.getSelectExpressions();
            assertEquals(selectExpressions.size(), 2);
            assertEquals(selectExpressions.get(0), ExpressionContext.forIdentifier("foo"));
            assertEquals(selectExpressions.get(0).toString(), "foo");
            assertEquals(selectExpressions.get(1), ExpressionContext.forIdentifier("bar"));
            assertEquals(selectExpressions.get(1).toString(), "bar");
            assertTrue(queryContext.getAliasMap().isEmpty());
            assertNull(queryContext.getFilter());
            List<OrderByExpressionContext> orderByExpressions = queryContext.getOrderByExpressions();
            assertNotNull(orderByExpressions);
            assertEquals(orderByExpressions.size(), 2);
            assertEquals(orderByExpressions.get(0), new OrderByExpressionContext(ExpressionContext.forIdentifier("bar"), true));
            assertEquals(orderByExpressions.get(0).toString(), "bar ASC");
            assertEquals(orderByExpressions.get(1).toString(), "foo DESC");
            assertNull(queryContext.getHavingFilter());
            assertEquals(queryContext.getLimit(), 100);
            assertEquals(queryContext.getOffset(), 50);
            assertEquals(queryContext.getColumns(), new HashSet<>(Arrays.asList("foo", "bar")));
            assertFalse(QueryContextUtils.isAggregationQuery(queryContext));
        }
    }
    // Distinct with order-by
    {
        String pqlQuery = "SELECT DISTINCT(foo, bar, foobar) FROM testTable ORDER BY bar DESC, foo LIMIT 15";
        String sqlQuery = "SELECT DISTINCT foo, bar, foobar FROM testTable ORDER BY bar DESC, foo LIMIT 15";
        QueryContext[] queryContexts = getQueryContexts(pqlQuery, sqlQuery);
        for (QueryContext queryContext : queryContexts) {
            assertEquals(queryContext.getTableName(), "testTable");
            List<ExpressionContext> selectExpressions = queryContext.getSelectExpressions();
            assertEquals(selectExpressions.size(), 1);
            assertEquals(selectExpressions.get(0), ExpressionContext.forFunction(new FunctionContext(FunctionContext.Type.AGGREGATION, "distinct", Arrays.asList(ExpressionContext.forIdentifier("foo"), ExpressionContext.forIdentifier("bar"), ExpressionContext.forIdentifier("foobar")))));
            assertEquals(selectExpressions.get(0).toString(), "distinct(foo,bar,foobar)");
            assertTrue(queryContext.getAliasMap().isEmpty());
            assertNull(queryContext.getFilter());
            assertNull(queryContext.getGroupByExpressions());
            List<OrderByExpressionContext> orderByExpressions = queryContext.getOrderByExpressions();
            assertNotNull(orderByExpressions);
            assertEquals(orderByExpressions.size(), 2);
            assertEquals(orderByExpressions.get(0), new OrderByExpressionContext(ExpressionContext.forIdentifier("bar"), false));
            assertEquals(orderByExpressions.get(0).toString(), "bar DESC");
            assertEquals(orderByExpressions.get(1), new OrderByExpressionContext(ExpressionContext.forIdentifier("foo"), true));
            assertEquals(orderByExpressions.get(1).toString(), "foo ASC");
            assertNull(queryContext.getHavingFilter());
            assertEquals(queryContext.getLimit(), 15);
            assertEquals(queryContext.getOffset(), 0);
            assertEquals(queryContext.getColumns(), new HashSet<>(Arrays.asList("foo", "bar", "foobar")));
            assertTrue(QueryContextUtils.isAggregationQuery(queryContext));
        }
    }
    // Transform with order-by
    {
        String query = "SELECT ADD(foo, ADD(bar, 123)), SUB('456', foobar) FROM testTable ORDER BY SUB(456, foobar) LIMIT 30, 20";
        QueryContext[] queryContexts = getQueryContexts(query, query);
