        }
        for (int i = 5; i < 10; i++) {
            Assert.assertFalse(onHeapBloomFilter.mightContain(Integer.toString(i)));
            Assert.assertFalse(offHeapBloomFilter.mightContain(Integer.toString(i)));
        }
    }
}

