@Test
public void testTransformFunctionPartitioner() {
    PartitionerConfig partitionerConfig = new PartitionerConfig.Builder().setPartitionerType(PartitionerFactory.PartitionerType.TRANSFORM_FUNCTION).build();
    try {
        PartitionerFactory.getPartitioner(partitionerConfig);
        fail("Should not create TRANSFORM_FUNCTION Partitioner without transform function");
    } catch (IllegalStateException e) {
        // expected
    }
    partitionerConfig = new PartitionerConfig.Builder().setPartitionerType(PartitionerFactory.PartitionerType.TRANSFORM_FUNCTION).setTransformFunction("bad function").build();
    try {
        PartitionerFactory.getPartitioner(partitionerConfig);
        fail("Should not create TRANSFORM_FUNCTION Partitioner for invalid transform function");
    } catch (IllegalArgumentException e) {
        // expected
    }
    partitionerConfig = new PartitionerConfig.Builder().setPartitionerType(PartitionerFactory.PartitionerType.TRANSFORM_FUNCTION).setTransformFunction("toEpochDays(timestamp)").build();
    Partitioner partitioner = PartitionerFactory.getPartitioner(partitionerConfig);
    assertEquals(partitioner.getClass(), TransformFunctionPartitioner.class);
    GenericRow row = new GenericRow();
    row.putValue("timestamp", 1587410614000L);
    assertEquals(partitioner.getPartition(row), "18372");
    partitionerConfig = new PartitionerConfig.Builder().setPartitionerType(PartitionerFactory.PartitionerType.TRANSFORM_FUNCTION).setTransformFunction("Groovy({a+b},a,b)").build();
    partitioner = PartitionerFactory.getPartitioner(partitionerConfig);
    row.putValue("a", 10);
    row.putValue("b", 20);
    assertEquals(partitioner.getPartition(row), "30");
    // mv column
    partitionerConfig = new PartitionerConfig.Builder().setPartitionerType(PartitionerFactory.PartitionerType.TRANSFORM_FUNCTION).setTransformFunction("Groovy({dMv[1]},dMv)").build();
    partitioner = PartitionerFactory.getPartitioner(partitionerConfig);
    row.putValue("dMv", new Object[] { 1, 2, 3 });
    assertEquals(partitioner.getPartition(row), "2");
}

