@Test
public void testPartitionFilter() {
    RecordFilterConfig filterConfig = new RecordFilterConfig.Builder().setRecordFilterType(RecordFilterFactory.RecordFilterType.FILTER_FUNCTION).setFilterFunction("Groovy({Integer.valueOf(colA) < 10 || Integer.valueOf(colB) > 20},colA, colB)").build();
    RecordFilter recordFilter = RecordFilterFactory.getRecordFilter(filterConfig);
    GenericRow row = new GenericRow();
    row.putValue("colA", "5");
    row.putValue("colB", "5");
    assertTrue(recordFilter.filter(row));
    row.putValue("colA", "15");
    row.putValue("colB", "30");
    assertTrue(recordFilter.filter(row));
    row.putValue("colA", 5);
    row.putValue("colB", 15);
    assertTrue(recordFilter.filter(row));
    row.putValue("colA", "10");
    row.putValue("colB", "20");
    assertFalse(recordFilter.filter(row));
}

