@Test
public void testSingleDaySingleSegment() throws Exception {
    SegmentProcessorConfig config = new SegmentProcessorConfig.Builder().setTableConfig(_tableConfig).setSchema(_pinotSchema).build();
    // Single day, Single segment
    File outputSegmentDir = new File(_baseDir, "output_directory_single_day_single_segment");
    // default configs
    FileUtils.deleteQuietly(outputSegmentDir);
    assertTrue(outputSegmentDir.mkdirs());
    SegmentProcessorFramework framework = new SegmentProcessorFramework(_singleDaySingleSegment, config, outputSegmentDir);
    framework.processSegments();
    framework.cleanup();
    assertEquals(outputSegmentDir.listFiles().length, 1);
    SegmentMetadataImpl segmentMetadata = new SegmentMetadataImpl(outputSegmentDir.listFiles()[0]);
    assertEquals(segmentMetadata.getTotalDocs(), 10);
    // partitioning
    config = new SegmentProcessorConfig.Builder().setTableConfig(_tableConfig).setSchema(_pinotSchema).setPartitionerConfigs(Lists.newArrayList(new PartitionerConfig.Builder().setPartitionerType(PartitionerFactory.PartitionerType.ROUND_ROBIN).setNumPartitions(3).build())).build();
    FileUtils.deleteQuietly(outputSegmentDir);
    assertTrue(outputSegmentDir.mkdirs());
    framework = new SegmentProcessorFramework(_singleDaySingleSegment, config, outputSegmentDir);
    framework.processSegments();
    framework.cleanup();
    assertEquals(outputSegmentDir.listFiles().length, 3);
    int totalDocs = 0;
    for (File segment : outputSegmentDir.listFiles()) {
        segmentMetadata = new SegmentMetadataImpl(segment);
        totalDocs += segmentMetadata.getTotalDocs();
        assertTrue(segmentMetadata.getTotalDocs() == 3 || segmentMetadata.getTotalDocs() == 4);
    }
    assertEquals(totalDocs, 10);
    // record filtering
    config = new SegmentProcessorConfig.Builder().setTableConfig(_tableConfig).setSchema(_pinotSchema).setRecordFilterConfig(new RecordFilterConfig.Builder().setRecordFilterType(RecordFilterFactory.RecordFilterType.FILTER_FUNCTION).setFilterFunction("Groovy({campaign == \"abc\"}, campaign)").build()).build();
    FileUtils.deleteQuietly(outputSegmentDir);
    assertTrue(outputSegmentDir.mkdirs());
    framework = new SegmentProcessorFramework(_singleDaySingleSegment, config, outputSegmentDir);
    framework.processSegments();
    framework.cleanup();
    assertEquals(outputSegmentDir.listFiles().length, 1);
    segmentMetadata = new SegmentMetadataImpl(outputSegmentDir.listFiles()[0]);
    assertEquals(segmentMetadata.getTotalDocs(), 5);
    // filtered everything
    config = new SegmentProcessorConfig.Builder().setTableConfig(_tableConfig).setSchema(_pinotSchema).setRecordFilterConfig(new RecordFilterConfig.Builder().setRecordFilterType(RecordFilterFactory.RecordFilterType.FILTER_FUNCTION).setFilterFunction("Groovy({clicks > 0}, clicks)").build()).build();
    FileUtils.deleteQuietly(outputSegmentDir);
    assertTrue(outputSegmentDir.mkdirs());
    framework = new SegmentProcessorFramework(_singleDaySingleSegment, config, outputSegmentDir);
    try {
        framework.processSegments();
        fail("Should fail for empty map output");
    } catch (IllegalStateException e) {
        framework.cleanup();
    }
    // record transformation
    Map<String, String> recordTransformationMap = new HashMap<>();
    recordTransformationMap.put("clicks", "times(clicks, 0)");
    config = new SegmentProcessorConfig.Builder().setTableConfig(_tableConfig).setSchema(_pinotSchema).setRecordTransformerConfig(new RecordTransformerConfig.Builder().setTransformFunctionsMap(recordTransformationMap).build()).build();
    FileUtils.deleteQuietly(outputSegmentDir);
    assertTrue(outputSegmentDir.mkdirs());
    framework = new SegmentProcessorFramework(_singleDaySingleSegment, config, outputSegmentDir);
    framework.processSegments();
    framework.cleanup();
    assertEquals(outputSegmentDir.listFiles().length, 1);
    segmentMetadata = new SegmentMetadataImpl(outputSegmentDir.listFiles()[0]);
    assertEquals(segmentMetadata.getTotalDocs(), 10);
    assertEquals(segmentMetadata.getColumnMetadataFor("clicks").getCardinality(), 1);
    // collection
    config = new SegmentProcessorConfig.Builder().setTableConfig(_tableConfig).setSchema(_pinotSchema).setCollectorConfig(new CollectorConfig.Builder().setCollectorType(CollectorFactory.CollectorType.ROLLUP).build()).build();
    FileUtils.deleteQuietly(outputSegmentDir);
    assertTrue(outputSegmentDir.mkdirs());
    framework = new SegmentProcessorFramework(_singleDaySingleSegment, config, outputSegmentDir);
    framework.processSegments();
    framework.cleanup();
    assertEquals(outputSegmentDir.listFiles().length, 1);
    segmentMetadata = new SegmentMetadataImpl(outputSegmentDir.listFiles()[0]);
    assertEquals(segmentMetadata.getTotalDocs(), 3);
    assertEquals(segmentMetadata.getColumnMetadataFor("campaign").getCardinality(), 3);
    // segment config
    config = new SegmentProcessorConfig.Builder().setTableConfig(_tableConfig).setSchema(_pinotSchema).setSegmentConfig(new SegmentConfig.Builder().setMaxNumRecordsPerSegment(4).build()).build();
    FileUtils.deleteQuietly(outputSegmentDir);
    assertTrue(outputSegmentDir.mkdirs());
    framework = new SegmentProcessorFramework(_singleDaySingleSegment, config, outputSegmentDir);
    framework.processSegments();
    framework.cleanup();
    assertEquals(outputSegmentDir.listFiles().length, 3);
    totalDocs = 0;
    for (File segment : outputSegmentDir.listFiles()) {
        segmentMetadata = new SegmentMetadataImpl(segment);
        totalDocs += segmentMetadata.getTotalDocs();
        assertTrue(segmentMetadata.getTotalDocs() == 4 || segmentMetadata.getTotalDocs() == 2);
    }
    assertEquals(totalDocs, 10);
}

