@Test
public void testValidateUpsertConfig() {
    Schema schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).build();
    TableConfig tableConfig = new TableConfigBuilder(TableType.OFFLINE).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "Upsert table is for realtime table only.");
    }
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "Upsert table must have primary key columns in the schema");
    }
    schema = new Schema.SchemaBuilder().setSchemaName(TABLE_NAME).addSingleValueDimension("myCol", FieldSpec.DataType.STRING).setPrimaryKeyColumns(Lists.newArrayList("myCol")).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "streamConfig must exist in the table config");
    }
    Map<String, String> streamConfigs = new HashMap<>();
    streamConfigs.put("stream.kafka.consumer.type", "highLevel");
    streamConfigs.put("streamType", "kafka");
    streamConfigs.put("stream.kafka.topic.name", "test");
    streamConfigs.put("stream.kafka.decoder.class.name", "org.apache.pinot.plugin.stream.kafka.KafkaJSONMessageDecoder");
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "Upsert table must use low-level streaming consumer type");
    }
    streamConfigs.put("stream.kafka.consumer.type", "simple");
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "Upsert table must use strict replica-group (i.e. strictReplicaGroup) based routing");
    }
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    } catch (Exception e) {
        Assert.fail("Should not fail upsert validation");
    }
    StarTreeIndexConfig starTreeIndexConfig = new StarTreeIndexConfig(Lists.newArrayList("myCol"), null, Collections.singletonList(new AggregationFunctionColumnPair(AggregationFunctionType.COUNT, "myCol").toColumnName()), 10);
    tableConfig = new TableConfigBuilder(TableType.REALTIME).setTableName(TABLE_NAME).setUpsertConfig(new UpsertConfig(UpsertConfig.Mode.FULL)).setRoutingConfig(new RoutingConfig(null, null, RoutingConfig.STRICT_REPLICA_GROUP_INSTANCE_SELECTOR_TYPE)).setStarTreeIndexConfigs(Lists.newArrayList(starTreeIndexConfig)).setStreamConfigs(streamConfigs).build();
    try {
        TableConfigUtils.validateUpsertConfig(tableConfig, schema);
    } catch (Exception e) {
        Assert.assertEquals(e.getMessage(), "The upsert table cannot have star-tree index.");
    }
}

