            List<String> group = groupByResult.getGroup();
            assertEquals(group.size(), 1);
            assertTrue(_values.contains(Integer.parseInt(group.get(0))));
            assertEquals(groupByResult.getValue(), Long.toString(4));
        }
    }
}

