@Test
public void testQueriesFromQueryFile() throws Exception {
    if (!_enabled) {
        return;
    }
    // Do not compare numDocsScanned
    QueryComparison.setCompareNumDocs(false);
    final AtomicInteger numFailedQueries = new AtomicInteger();
    try (BufferedReader responseFileReader = new BufferedReader(new FileReader(_responseFile))) {
        for (File realtimeAvroFile : _realtimeAvroFiles) {
            // Push one avro file into the Kafka topic
            pushAvroIntoKafka(Collections.singletonList(realtimeAvroFile));
            try (BufferedReader queryFileReader = new BufferedReader(new FileReader(_queryFile))) {
                // Set the expected COUNT(*) result and wait for all documents loaded
                responseFileReader.mark(4096);
                _countStarResult = JsonUtils.stringToJsonNode(responseFileReader.readLine()).get("totalDocs").asLong();
                responseFileReader.reset();
                waitForAllDocsLoaded(600_000L);
                // Run queries in multiple threads
                ExecutorService executorService = new ThreadPoolExecutor(4, 4, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>(10), new ThreadPoolExecutor.CallerRunsPolicy());
                String query;
                while ((query = queryFileReader.readLine()) != null) {
                    String currentQuery = query;
                    JsonNode expectedResponse = JsonUtils.stringToJsonNode(responseFileReader.readLine());
                    executorService.execute(new Runnable() {

                        @Override
                        public void run() {
                            try {
                                JsonNode actualResponse = postQuery(new PinotQueryRequest("pql", currentQuery), "http://localhost:" + BROKER_PORT);
                                if (QueryComparison.compareWithEmpty(actualResponse, expectedResponse) == QueryComparison.ComparisonStatus.FAILED) {
                                    numFailedQueries.getAndIncrement();
                                    System.out.println("Query comparison failed for query: " + currentQuery + "\nActual: " + actualResponse.toString() + "\nExpected: " + expectedResponse.toString());
                                }
                            } catch (Exception e) {
                                numFailedQueries.getAndIncrement();
                                System.out.println("Caught exception while comparing query: " + currentQuery);
                                e.printStackTrace();
                            }
                        }
                    });
                }
                executorService.shutdown();
                executorService.awaitTermination(10, TimeUnit.MINUTES);
            }
        }
    }
    Assert.assertEquals(numFailedQueries.get(), 0, "Caught " + numFailedQueries + " failed queries");
}

@Test
public void testQueries() throws Exception {
    // Select column created with transform function
    String sqlQuery = "Select millisSinceEpoch from " + DEFAULT_TABLE_NAME;
    JsonNode response = postSqlQuery(sqlQuery);
    assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(0).asText(), "millisSinceEpoch");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnDataTypes").get(0).asText(), "LONG");
    // Select column created with transform function
    sqlQuery = "Select AmPm, DepTime from " + DEFAULT_TABLE_NAME;
    response = postSqlQuery(sqlQuery);
    assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(0).asText(), "AmPm");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(1).asText(), "DepTime");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnDataTypes").get(0).asText(), "STRING");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnDataTypes").get(1).asText(), "INT");
    for (int i = 0; i < response.get("resultTable").get("rows").size(); i++) {
        String amPm = response.get("resultTable").get("rows").get(i).get(0).asText();
        int depTime = response.get("resultTable").get("rows").get(i).get(1).asInt();
        Assert.assertEquals(amPm, (depTime < 1200) ? "AM" : "PM");
    }
    // Select column created with transform function - offline table
    sqlQuery = "Select AmPm, DepTime from " + DEFAULT_TABLE_NAME + "_OFFLINE";
    response = postSqlQuery(sqlQuery);
    assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(0).asText(), "AmPm");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(1).asText(), "DepTime");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnDataTypes").get(0).asText(), "STRING");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnDataTypes").get(1).asText(), "INT");
    for (int i = 0; i < response.get("resultTable").get("rows").size(); i++) {
        String amPm = response.get("resultTable").get("rows").get(i).get(0).asText();
        int depTime = response.get("resultTable").get("rows").get(i).get(1).asInt();
        Assert.assertEquals(amPm, (depTime < 1200) ? "AM" : "PM");
    }
    // Select column created with transform - realtime table
    sqlQuery = "Select AmPm, DepTime from " + DEFAULT_TABLE_NAME + "_REALTIME";
    response = postSqlQuery(sqlQuery);
    assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(0).asText(), "AmPm");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnNames").get(1).asText(), "DepTime");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnDataTypes").get(0).asText(), "STRING");
    assertEquals(response.get("resultTable").get("dataSchema").get("columnDataTypes").get(1).asText(), "INT");
    for (int i = 0; i < response.get("resultTable").get("rows").size(); i++) {
        String amPm = response.get("resultTable").get("rows").get(i).get(0).asText();
        int depTime = response.get("resultTable").get("rows").get(i).get(1).asInt();
        Assert.assertEquals(amPm, (depTime < 1200) ? "AM" : "PM");
    }
    // Check there's no values that should've been filtered
    sqlQuery = "Select * from " + DEFAULT_TABLE_NAME + "  where AirlineID = 19393 or ArrDelayMinutes <= 5";
    response = postSqlQuery(sqlQuery);
    Assert.assertEquals(response.get("resultTable").get("rows").size(), 0);
    // Check there's no values that should've been filtered - realtime table
    sqlQuery = "Select * from " + DEFAULT_TABLE_NAME + "_REALTIME" + "  where AirlineID = 19393 or ArrDelayMinutes <= 5";
    response = postSqlQuery(sqlQuery);
    Assert.assertEquals(response.get("resultTable").get("rows").size(), 0);
    // Check there's no values that should've been filtered - offline table
    sqlQuery = "Select * from " + DEFAULT_TABLE_NAME + "_OFFLINE" + "  where AirlineID = 19393 or ArrDelayMinutes <= 5";
    response = postSqlQuery(sqlQuery);
    Assert.assertEquals(response.get("resultTable").get("rows").size(), 0);
