    groupName2.add("dimensionName2");
    overrideThreshold.put(groupName2, 4);
    // Compare results
    Assert.assertEquals(sizeSeverityFilter.getOverrideThreshold(), overrideThreshold);
    Assert.assertEquals(sizeSeverityFilter.getThreshold(), 10);
}

