@Test
public void testTranslateMetricToYaml() {
    DatasetConfigDTO datasetConfigDTO = new DatasetConfigDTO();
    datasetConfigDTO.setTimeColumn("timeCol");
    datasetConfigDTO.setTimeUnit(TimeUnit.DAYS);
    datasetConfigDTO.setTimeDuration(1);
    datasetConfigDTO.setTimeFormat("SIMPLE_DATE_FORMAT:yyyyMMdd");
    datasetConfigDTO.setTimezone("US/Pacific");
    String datasetConfigYaml = this.anomalyDetectionResource.translateDatasetToYaml(datasetConfigDTO);
    Map<String, Object> restoredConfigs = ConfigUtils.getMap(yaml.load(datasetConfigYaml));
    Assert.assertTrue(restoredConfigs.containsKey("timeColumn") && restoredConfigs.get("timeColumn").equals("timeCol"), "Incorrect timeColumn: " + restoredConfigs.get("timeColumn"));
    Assert.assertTrue(restoredConfigs.containsKey("timeUnit") && restoredConfigs.get("timeUnit").equals("DAYS"), "Incorrect timeUnit: " + restoredConfigs.get("timeUnit"));
    Assert.assertTrue(restoredConfigs.containsKey("timeDuration") && (restoredConfigs.get("timeDuration")).equals("1"), "Incorrect timeDuration: " + restoredConfigs.get("timeDuration"));
    Assert.assertTrue(restoredConfigs.containsKey("timeFormat") && restoredConfigs.get("timeFormat").equals("SIMPLE_DATE_FORMAT:yyyyMMdd"), "Incorrect timeFormat: " + restoredConfigs.get("timeFormat"));
    Assert.assertTrue(restoredConfigs.containsKey("timezone") && restoredConfigs.get("timezone").equals("US/Pacific"), "Incorrect timezone: " + restoredConfigs.get("timezone"));
}

