@Test
public void testJoinOuterObject() {
    DataFrame left = new DataFrame().addSeriesObjects("key", DataFrame.Tuple.buildFrom("a", "a"), DataFrame.Tuple.buildFrom("a", "b")).addSeries("leftValue", 1, 2);
    DataFrame right = new DataFrame().addSeriesObjects("key", DataFrame.Tuple.buildFrom("b", "b"), DataFrame.Tuple.buildFrom("a", "b")).addSeries("rightValue", "3", "4");
    DataFrame joined = left.joinOuter(right, "key");
    Assert.assertEquals(joined.size(), 3);
    Assert.assertEquals(joined.get("key").type(), Series.SeriesType.OBJECT);
