    value = 0.00135;
    Assert.assertEquals(ThirdEyeUtils.getRoundedValue(value), "0.0014");
    value = 0;
    Assert.assertEquals(ThirdEyeUtils.getRoundedValue(value), "0");
    value = 0.0000;
    Assert.assertEquals(ThirdEyeUtils.getRoundedValue(value), "0");
    value = 0.0000009;
    Assert.assertEquals(ThirdEyeUtils.getRoundedValue(value), "0");
    value = 0.00123456789;
    Assert.assertEquals(ThirdEyeUtils.getRoundedValue(value), "0.0012");
}

